<?php
namespace App\Policies;use App\Domain\Tenancy\TenantContext;use App\Models\{Proposal,User};final class ProposalPolicy{private function m(User$u):bool{return$u->memberships()->where(['tenant_id'=>app(TenantContext::class)->id(),'status'=>'ACTIVE'])->exists();}public function viewAny(User$u):bool{return$this->m($u);}public function view(User$u,Proposal$p):bool{return$this->m($u)&&$p->tenant_id===app(TenantContext::class)->id();}public function create(User$u):bool{return$this->m($u);}public function update(User$u,Proposal$p):bool{return$this->view($u,$p)&&in_array($p->status,['DRAFT','DISCLOSURES_PENDING','DOCUMENTS_PENDING'],true);}public function delete(User$u,Proposal$p):bool{return false;}}
